// h() membuat simpul virtual DOM: objek biasa, belum menyentuh layar.
function h(tag, props, ...anak) {
  return { tag, props: props || {}, anak: anak.flat() };
}

function escape(teks) {
  return String(teks).replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function renderToString(simpul) {
  if (typeof simpul !== 'object') return escape(simpul);
  if (typeof simpul.tag === 'function') {
    // Komponen: panggil fungsinya, render hasilnya.
    return renderToString(simpul.tag({ ...simpul.props, anak: simpul.anak }));
  }
  const attr = Object.entries(simpul.props)
    .map(([k, v]) => ` ${k}="${escape(v)}"`).join('');
  return `<${simpul.tag}${attr}>${simpul.anak.map(renderToString).join('')}</${simpul.tag}>`;
}

