// Pipeline CSS mini: tiap "plugin" menerima teks CSS dan mengembalikan teks baru.
const css = `
/* tombol utama */
.tombol {
  user-select: none;
  color: #ffffff;
  margin: 0px;
}
.sisa-lama {
  color: red;
}
`;

const dipakaiDiHtml = ['tombol']; // hasil memindai HTML

function buangYangTakDipakai(teks) {
  return teks.replace(/\.([\w-]+)\s*\{[^}]*\}/g, (aturan, nama) =>
    (dipakaiDiHtml.includes(nama) ? aturan : ''));
}

function tambahPrefix(teks) {
  return teks.replace(/(\s*)user-select:([^;]+);/g,
    '$1-webkit-user-select:$2;$1user-select:$2;');
}

function kecilkan(teks) {
  return teks
    .replace(/\/\*[\s\S]*?\*\//g, '')   // buang komentar
    .replace(/#ffffff/gi, '#fff')       // warna versi pendek
    .replace(/\b0px\b/g, '0')           // 0px sama dengan 0
    .replace(/\s+/g, ' ')
    .replace(/\s*([{};:])\s*/g, '$1')
    .replace(/;}/g, '}')
    .trim();
}

const pipeline = [buangYangTakDipakai, tambahPrefix, kecilkan];
const hasil = pipeline.reduce((teks, plugin) => plugin(teks), css);
console.log(hasil);
console.log(`${css.length} karakter jadi ${hasil.length} karakter`);

