// Empat "berkas" ES Module, disimpan sebagai teks biasa.
const berkas = {
  'main.js': [
    "import { formatRupiah } from './uang.js';",
    "import { sapa } from './teks.js';",
    "console.log(sapa('Dina'), formatRupiah(15000));",
  ].join('\n'),
  'uang.js': [
    "export function formatRupiah(n) { return 'Rp' + n; }",
    "export function formatDolar(n) { return '$' + n; }",
  ].join('\n'),
  'teks.js': [
    "export function sapa(nama) { return 'Halo ' + nama; }",
    "export function teriak(nama) { return nama.toUpperCase(); }",
  ].join('\n'),
  'lama.js': "export function tidakDipakai() {}",
};

const POLA_IMPORT = /import \{([^}]+)\} from '\.\/([^']+)'/g;
const POLA_EKSPOR = /export function (\w+)/g;

const graf = {};
const dipakai = {};

function kunjungi(nama) {
  if (graf[nama]) return;
  graf[nama] = [];
  for (const [, daftar, tujuan] of berkas[nama].matchAll(POLA_IMPORT)) {
    graf[nama].push(tujuan);
    dipakai[tujuan] = dipakai[tujuan] || new Set();
    for (const n of daftar.split(',')) dipakai[tujuan].add(n.trim());
    kunjungi(tujuan);
  }
}

kunjungi('main.js');

console.log('Graf modul dari main.js:');
for (const [nama, anak] of Object.entries(graf)) {
  console.log(`  ${nama} -> ${anak.join(', ') || '(tidak ada)'}`);
}
console.log('Dibuang tree-shaking:');
for (const nama of Object.keys(berkas)) {
  if (!graf[nama]) {
    console.log(`  ${nama}: seluruh modul (nggak pernah di-import)`);
    continue;
  }
  for (const [, ekspor] of berkas[nama].matchAll(POLA_EKSPOR)) {
    if (dipakai[nama] && !dipakai[nama].has(ekspor)) {
      console.log(`  ${nama}: ${ekspor}`);
    }
  }
}

