// Bentuk sederhana fungsi jsx() yang dipanggil kode hasil kompilasi JSX.
function jsx(type, props, key) {
  return { type, props, key };
}

function render(el) {
  if (typeof el === 'string' || typeof el === 'number') return String(el);
  if (Array.isArray(el)) return el.map(render).join('');
  if (typeof el.type === 'function') return render(el.type(el.props));
  const { children, ...atribut } = el.props;
  const attr = Object.entries(atribut)
    .map(([k, v]) => ` ${k === 'className' ? 'class' : k}="${v}"`)
    .join('');
  const isi = children === undefined ? '' : render(children);
  return `<${el.type}${attr}>${isi}</${el.type}>`;
}

