function tukar(html, id, potongan, cara) {
  const buka = html.indexOf('id="' + id + '"');
  const awalTag = html.lastIndexOf('<', buka);
  const tag = html.slice(awalTag + 1, buka).trim();
  const akhirBuka = html.indexOf('>', buka) + 1;
  const tutup = html.indexOf('</' + tag + '>', akhirBuka);
  if (cara === 'beforeend') {
    return html.slice(0, tutup) + potongan + html.slice(tutup);
  }
  return html.slice(0, akhirBuka) + potongan + html.slice(tutup);
}

