function peran(el) {
  if (/^h[1-6]$/.test(el.tag)) return 'heading';
  if (el.tag === 'button') return 'button';
  if (el.tag === 'input' && ['text', 'email'].includes(el.type)) return 'textbox';
  return null; // div yang bisa diklik dan input password nggak punya peran
}

function nama(el) {
  if (el.tag === 'input') {
    const label = halaman.find((l) => l.tag === 'label' && l.untuk === el.id);
    return label ? label.teks : '';
  }
  return el.teks || '';
}

function getByRole(role, opsi = {}) {
  const cocok = halaman.filter((el) => peran(el) === role
    && (opsi.name === undefined || nama(el) === opsi.name));
  if (cocok.length === 1) return cocok[0];
  const ada = halaman.filter(peran).map((el) => peran(el) + ' "' + nama(el) + '"');
  throw new Error((cocok.length ? 'lebih dari satu ' : 'tidak ketemu ')
    + role + ' "' + opsi.name + '"\n  yang ada: ' + ada.join(', '));
}

