// Tiga "berkas" Markdown dengan front matter, seperti di folder konten SSG
const konten = {
  'index.md': '---\njudul: Beranda\n---\n# Kafe Senja\nBuka tiap hari.',
  'menu.md': '---\njudul: Menu\n---\n# Menu\nKopi susu dan teh melati.',
  'draf.md': '---\njudul: Promo\ndraf: ya\n---\n# Promo rahasia',
};

function bacaFrontMatter(teks) {
  const [, kepala, isi] = teks.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
  const data = {};
  for (const baris of kepala.split('\n')) {
    const [k, ...v] = baris.split(':');
    data[k.trim()] = v.join(':').trim();
  }
  return { data, isi };
}

function markdownKeHtml(isi) {
  return isi.split('\n').map((b) =>
    b.startsWith('# ') ? '<h1>' + b.slice(2) + '</h1>' : '<p>' + b + '</p>').join('');
}

const layout = (judul, badan) => '<title>' + judul + '</title>' + badan;

for (const [nama, teks] of Object.entries(konten)) {
  const { data, isi } = bacaFrontMatter(teks);
  if (data.draf === 'ya') {
    console.log(nama + ' dilewati (draf)');
    continue;
  }
  const keluar = nama.replace(/\.md$/, '.html');
  console.log(keluar + ': ' + layout(data.judul, markdownKeHtml(isi)));
}

// Logika "headless": perilaku dan atribut ARIA, tanpa satu baris gaya pun
function buatDisclosure(id) {
  let terbuka = false;
  return {
    toggle() { terbuka = !terbuka; },
    propsTombol() {
      return { 'aria-expanded': String(terbuka), 'aria-controls': id + '-isi', id: id };
    },
    propsPanel() {
      return { id: id + '-isi', role: 'region', 'aria-labelledby': id, hidden: !terbuka };
    },
  };
}

function render(props, tag, isi) {
  const attr = Object.entries(props)
    .filter(([, v]) => v !== false)
    .map(([k, v]) => (v === true ? k : k + '="' + v + '"'))
    .join(' ');
  return '<' + tag + ' ' + attr + '>' + isi + '</' + tag + '>';
}

