// Merakit modul WebAssembly byte demi byte (semua angka di sini < 128,
// jadi satu byte LEB128 cukup untuk tiap angka)
const teks = (s) => [s.length, ...Buffer.from(s)];
const bagian = (id, isi) => [id, isi.length, ...isi];
const daftar = (...isi) => [isi.length, ...isi.flat()];

const I32 = 0x7f;
const bytes = new Uint8Array([
  0x00, 0x61, 0x73, 0x6d, // "\0asm"
  0x01, 0x00, 0x00, 0x00, // versi 1
  // tipe 0: (i32, i32) -> i32, tipe 1: (i32) -> ()
  ...bagian(1, daftar([0x60, 2, I32, I32, 1, I32], [0x60, 1, I32, 0])),
  // impor: fungsi env.lapor (tipe 1) dan memori env.mem (minimal 1 halaman)
  ...bagian(2, daftar(
    [...teks('env'), ...teks('lapor'), 0x00, 1],
    [...teks('env'), ...teks('mem'), 0x02, 0x00, 1],
  )),
  // dua fungsi buatan sendiri, keduanya bertipe 0
  ...bagian(3, daftar([0], [0])),
  // ekspor: tambah = fungsi 1, tambahMemori = fungsi 2 (fungsi 0 = lapor)
  ...bagian(7, daftar(
    [...teks('tambah'), 0x00, 1],
    [...teks('tambahMemori'), 0x00, 2],
  )),
  ...bagian(10, daftar(
    // tambah(a, b): local.get 0, local.get 1, i32.add, end
    (() => { const k = [0, 0x20, 0, 0x20, 1, 0x6a, 0x0b]; return [k.length, ...k]; })(),
    // tambahMemori(pa, pb): baca dua i32 dari memori, jumlahkan, lapor, kembalikan
    (() => {
      const k = [1, 1, I32, // satu variabel lokal i32 (indeks 2)
        0x20, 0, 0x28, 2, 0, // local.get 0, i32.load
        0x20, 1, 0x28, 2, 0, // local.get 1, i32.load
        0x6a, 0x22, 2, // i32.add, local.tee 2
        0x10, 0, // call lapor
        0x20, 2, 0x0b]; // local.get 2, end
      return [k.length, ...k];
    })(),
  )),
]);

