function urai(v) {
  return v.split('.').map(Number);
}

function banding(a, b) {
  for (let i = 0; i < 3; i++) {
    if (a[i] !== b[i]) return a[i] - b[i];
  }
  return 0;
}

function cocok(versi, rentang) {
  const v = urai(versi);
  if (rentang.startsWith('^')) {
    const r = urai(rentang.slice(1));
    if (banding(v, r) < 0) return false;
    if (r[0] > 0) return v[0] === r[0];
    if (r[1] > 0) return v[0] === 0 && v[1] === r[1];
    return v[0] === 0 && v[1] === 0 && v[2] === r[2];
  }
  if (rentang.startsWith('~')) {
    const r = urai(rentang.slice(1));
    return banding(v, r) >= 0 && v[0] === r[0] && v[1] === r[1];
  }
  return banding(v, urai(rentang)) === 0;
}

let terbaik = null;
