function useState(awal) {
  const i = indeks++;
  if (i >= hooks.length) hooks.push(awal);
  const setState = (baru) => {
    const nilai = typeof baru === 'function' ? baru(hooks[i]) : baru;
    if (Object.is(nilai, hooks[i])) return;
    hooks[i] = nilai;
    perluRender = true;
  };
  return [hooks[i], setState];
}

function render() {
  indeks = 0;
  nomor++;
  hasil = komponen();
  console.log(`render #${nomor}: ${hasil.teks}`);
}

function pasang(fn) {
  komponen = fn;
  hooks = [];
  nomor = 0;
  render();
}

