function createStore(reducer) {
  let state = reducer(undefined, { type: '@@init' });
  let pendengar = [];
  return {
    getState: () => state,
    dispatch(action) {
      state = reducer(state, action);
      pendengar.slice().forEach((f) => f());
      return action;
    },
    subscribe(f) {
      pendengar.push(f);
      return () => {
        pendengar = pendengar.filter((g) => g !== f);
      };
    },
  };
}

function combineReducers(peta) {
  return (state = {}, action) => {
    const baru = {};
    let berubah = false;
    for (const kunci of Object.keys(peta)) {
      baru[kunci] = peta[kunci](state[kunci], action);
      if (baru[kunci] !== state[kunci]) berubah = true;
    }
    return berubah ? baru : state;
  };
}

function hitung(state = 0, action) {
  switch (action.type) {
    case 'hitung/tambah':
      return state + (action.jumlah ?? 1);
    case 'hitung/reset':
      return 0;
    default:
      return state;
  }
}

function todo(state = [], action) {
  switch (action.type) {
    case 'todo/tambah':
      return [...state, { id: state.length + 1, teks: action.teks, selesai: false }];
    case 'todo/selesai':
      return state.map((t) => (t.id === action.id ? { ...t, selesai: true } : t));
    default:
      return state;
  }
}

