function escapeHtml(teks) {
  return String(teks)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function ambil(objek, jalur) {
  return jalur.split('.').reduce((o, k) => (o == null ? undefined : o[k]), objek);
}

function reactive(objek, saatBerubah) {
  return new Proxy(objek, {
    get(target, kunci) {
      const v = Reflect.get(target, kunci);
      return typeof v === 'object' && v !== null ? reactive(v, saatBerubah) : v;
    },
    set(target, kunci, nilai) {
      if (Object.is(target[kunci], nilai)) {
        console.log(`(${kunci} tidak berubah, tidak render)`);
        return true;
      }
      Reflect.set(target, kunci, nilai);
      saatBerubah(kunci);
      return true;
    },
  });
}

function buatApp({ template, data, computed }) {
  let nomor = 0;
  const state = reactive(data, (kunci) => render(`${kunci} berubah`));

  function nilaiDari(jalur) {
    const kepala = jalur.split('.')[0];
    if (kepala in computed) {
      return ambil({ [kepala]: computed[kepala](state) }, jalur);
    }
    return ambil(state, jalur);
  }

  function render(alasan) {
    nomor++;
    const html = template.replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, jalur) => {
      const v = nilaiDari(jalur);
      return v === undefined || v === null ? '' : escapeHtml(v);
    });
    console.log(`render #${nomor} (${alasan}): ${html}`);
  }

  render('awal');
  return state;
}

