function cariElemen(html, id) {
  const pola = new RegExp('<([a-z0-9]+)([^>]*)\\sid="' + id + '"([^>]*)>');
  const m = pola.exec(html);
  if (!m) return null;
  const tag = m[1];
  const awal = m.index;
  const akhirBuka = awal + m[0].length;
  let tingkat = 1;
  const pencari = new RegExp('<' + tag + '[\\s>]|</' + tag + '>', 'g');
  pencari.lastIndex = akhirBuka;
  let t;
  while ((t = pencari.exec(html))) {
    tingkat += t[0].startsWith('</') ? -1 : 1;
    if (tingkat === 0) {
      return { awal, akhirBuka, awalTutup: t.index, akhir: t.index + t[0].length, buka: m[0] };
    }
  }
  return null;
}

function atribut(tagBuka, nama) {
  const m = new RegExp('\\s' + nama + '="([^"]*)"').exec(tagBuka);
  return m ? m[1] : null;
}

function tukar(html, el, isi, cara) {
  switch (cara) {
    case 'innerHTML': return html.slice(0, el.akhirBuka) + isi + html.slice(el.awalTutup);
    case 'outerHTML': return html.slice(0, el.awal) + isi + html.slice(el.akhir);
    case 'beforeend': return html.slice(0, el.awalTutup) + isi + html.slice(el.awalTutup);
    case 'afterbegin': return html.slice(0, el.akhirBuka) + isi + html.slice(el.akhirBuka);
    default: return html;
  }
}

const klik = fs.readFileSync(0, 'utf8').split('\n').map((s) => s.trim()).filter(Boolean);
for (const id of klik) {
  const el = cariElemen(halaman, id);
  if (!el) {
    console.log('klik #' + id + ': elemen tidak ada');
    continue;
  }
  const url = atribut(el.buka, 'hx-get');
  if (!url) {
    console.log('klik #' + id + ': tanpa hx-get');
    continue;
  }
  const target = (atribut(el.buka, 'hx-target') || '#' + id).slice(1);
  const cara = atribut(el.buka, 'hx-swap') || 'innerHTML';
  if (!(url in server)) {
    console.log('klik #' + id + ': GET ' + url + ' -> 404, halaman tidak berubah');
    continue;
  }
  const sasaran = cariElemen(halaman, target);
  if (!sasaran) {
    console.log('klik #' + id + ': target #' + target + ' tidak ada');
    continue;
  }
  halaman = tukar(halaman, sasaran, server[url], cara);
  console.log('klik #' + id + ': GET ' + url + ' -> ' + cara + ' #' + target);
}
