// 0 = statis, 1 = dinamis [x], 2 = catch-all [...x]
function jenis(seg) {
  if (seg.startsWith('[...')) return 2;
  if (seg.startsWith('[')) return 1;
  return 0;
}

const rute = [];
for (const b of berkas) {
