  const segmen = b.slice(4, -8).split('/').filter((s) => s && !/^\(.*\)$/.test(s));
  if (b === 'app/page.js') segmen.length = 0;
  const jalur = '/' + segmen.join('/');
  const ada = rute.find((r) => r.jalur === jalur);
  if (ada) {
    console.log('BENTROK ' + jalur + ': ' + ada.berkas + ' dan ' + b);
    continue;
  }
  rute.push({ jalur, segmen, berkas: b, kunci: segmen.map(jenis) });
}

function bandingkan(a, b) {
  const n = Math.min(a.kunci.length, b.kunci.length);
  for (let i = 0; i < n; i++) {
    if (a.kunci[i] !== b.kunci[i]) return a.kunci[i] - b.kunci[i];
  }
  if (a.kunci.length !== b.kunci.length) return a.kunci.length - b.kunci.length;
  return a.jalur < b.jalur ? -1 : a.jalur > b.jalur ? 1 : 0;
}
