function cocok(r, bagian) {
  const params = {};
  for (let i = 0; i < r.segmen.length; i++) {
    const s = r.segmen[i];
    const k = r.kunci[i];
    if (i >= bagian.length) return null;
    if (k === 2) {
      params[s.slice(4, -1)] = bagian.slice(i);
      return params;
    }
    if (k === 1) params[s.slice(1, -1)] = bagian[i];
    else if (s !== bagian[i]) return null;
  }
  return r.segmen.length === bagian.length ? params : null;
}

