// Kahn: ambil paket yang semua dependensinya sudah selesai, seri dipecah alfabet
function urutanTopologis() {
  const sisa = {};
  for (const [n, p] of Object.entries(paket)) sisa[n] = p.deps.length;
  const urut = [];
  const siap = Object.keys(sisa).filter((n) => sisa[n] === 0).sort();
  while (siap.length) {
    const n = siap.shift();
    urut.push(n);
    for (const [m, p] of Object.entries(paket)) {
      if (p.deps.includes(n) && --sisa[m] === 0) {
        siap.push(m);
        siap.sort();
      }
    }
  }
  return urut;
}

function cariSiklus(mulai) {
  const jejak = [];
  const dikunjungi = new Set();
  function telusur(n) {
    const i = jejak.indexOf(n);
    if (i >= 0) return jejak.slice(i).concat(n);
    if (dikunjungi.has(n)) return null;
    dikunjungi.add(n);
    jejak.push(n);
    for (const d of [...paket[n].deps].sort()) {
      const h = telusur(d);
      if (h) return h;
    }
    jejak.pop();
    return null;
  }
  return telusur(mulai);
}

const urut = urutanTopologis();
