const fs = require('fs');

const langkah = fs.readFileSync(0, 'utf8').split('\n').map((s) => s.trim()).filter(Boolean);

function simulasi(strategi) {
  console.log('== ' + strategi + ' ==');
  const versiServer = {};
  const cache = new Map();
  const versi = (url) => versiServer[url] || 'v1';

  // jaringan palsu: null berarti offline
  function jaringan(url, online) {
    if (!online) return null;
    return url + ' ' + versi(url);
  }

  langkah.forEach((baris, i) => {
    const no = String(i + 1).padStart(2);
    const [aksi, url, nilai] = baris.split(/\s+/);
    if (aksi === 'ubah') {
      versiServer[url] = nilai;
      console.log(no + ' server: ' + url + ' sekarang ' + nilai);
      return;
    }
    const online = aksi === 'online';
    const awal = no + ' ' + aksi.padEnd(7) + ' ' + url.padEnd(7) + ' -> ';
    const disimpan = cache.get(url);

    if (strategi === 'cache-first') {
      if (disimpan) return console.log(awal + 'cache    ' + disimpan);
      const r = jaringan(url, online);
      if (!r) return console.log(awal + 'GAGAL (offline, belum ada di cache)');
      cache.set(url, r);
      return console.log(awal + 'jaringan ' + r + ' (disimpan)');
    }

    if (strategi === 'network-first') {
      const r = jaringan(url, online);
      if (r) {
        cache.set(url, r);
        return console.log(awal + 'jaringan ' + r + ' (disimpan)');
      }
      if (disimpan) return console.log(awal + 'cache    ' + disimpan + ' (cadangan offline)');
      return console.log(awal + 'GAGAL (offline, belum ada di cache)');
    }

    // stale-while-revalidate
    if (disimpan) {
      const r = jaringan(url, online);
      let catatan = '';
      if (r && r !== disimpan) {
        cache.set(url, r);
        catatan = ' (latar: cache diperbarui ke ' + r.split(' ')[1] + ')';
      }
      return console.log(awal + 'cache    ' + disimpan + catatan);
    }
    const r = jaringan(url, online);
    if (!r) return console.log(awal + 'GAGAL (offline, belum ada di cache)');
    cache.set(url, r);
    return console.log(awal + 'jaringan ' + r + ' (disimpan)');
  });
}

for (const s of ['cache-first', 'network-first', 'stale-while-revalidate']) simulasi(s);

const fs = require('fs');
