// ---------- 1. reaktivitas: signal, computed, effect (bab 03) ----------
let efekAktif = null;

function signal(awal) {
  let nilai = awal;
  const pelanggan = new Set();
  return {
    get value() {
      if (efekAktif) pelanggan.add(efekAktif);
      return nilai;
    },
    set value(baru) {
      if (Object.is(baru, nilai)) return;
      nilai = baru;
      for (const f of [...pelanggan]) f();
    },
  };
}

function effect(fn) {
  const jalan = () => {
    const lama = efekAktif;
    efekAktif = jalan;
    try { fn(); } finally { efekAktif = lama; }
  };
  jalan();
}

function computed(fn) {
  const hasil = signal(undefined);
  effect(() => { hasil.value = fn(); });
  return { get value() { return hasil.value; } };
}

// ---------- 2. komponen: h dan renderToString (bab 03) ----------
const KOSONG = new Set(['img', 'br', 'meta', 'link', 'input', 'hr']);

function h(tag, props, ...anak) {
  const datar = anak.flat(Infinity).filter((a) => a !== null && a !== false && a !== undefined);
  if (typeof tag === 'function') return tag({ ...(props || {}), children: datar });
  return { tag, props: props || {}, anak: datar };
}

function escape(teks) {
  return String(teks).replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function renderToString(v) {
  if (typeof v === 'string' || typeof v === 'number') return escape(v);
  const attr = Object.entries(v.props)
    .map(([k, x]) => ' ' + k + '="' + escape(x) + '"').join('');
  if (KOSONG.has(v.tag)) return '<' + v.tag + attr + '>';
  return '<' + v.tag + attr + '>' + v.anak.map(renderToString).join('') + '</' + v.tag + '>';
}

// ---------- 3. pemeriksa aksesibilitas (bab 02) ----------
function periksaA11y(v, keluhan) {
  if (typeof v !== 'object') return keluhan;
  if (v.tag === 'img' && !('alt' in v.props)) {
    keluhan.push('<img src="' + v.props.src + '"> tanpa alt');
  }
  v.anak.forEach((a) => periksaA11y(a, keluhan));
  return keluhan;
}

